export function resolveProblem(slugOrTitle) {
  if (!slugOrTitle) return null;
  const key = String(slugOrTitle).toLowerCase().trim().replace(/[^a-z0-9]/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '');
  return PROBLEM_CATALOG[key] || PROBLEM_CATALOG[String(slugOrTitle).toLowerCase().trim()] || null;
}
